template <class Call>
bool Run(const core::QueryArguments &a, std::vector<core::AuxRow> &out, Call call) {
  int64_t p1 = 0;
  if (!kit::ArgI64(a, 0, 0, p1))
    return false;
  std::string p2;
  if (!kit::ArgText(a, 1, p2))
    return false;
  std::string p3;
  if (!kit::ArgText(a, 2, p3))
    return false;
  secq6vgen_result *r = call(p1, reinterpret_cast<const uint8_t *>(p2.data()), p2.size(), reinterpret_cast<const uint8_t *>(p3.data()), p3.size());
  if (!r)
    return false;
  const size_t n = secq6vgen_result_len(r);
  out.reserve(out.size() + n);
  for (size_t i = 0; i < n; ++i) {
    core::AuxRow row;
    {
      const uint8_t *b0 = nullptr;
      size_t l0 = 0;
      row.values.push_back(secq6vgen_result_c0(r, i, &b0, &l0) ? kit::OutText(b0, l0) : kit::OutNull(core::AuxType::String));
    }
    {
      const uint8_t *b1 = nullptr;
      size_t l1 = 0;
      row.values.push_back(secq6vgen_result_c1(r, i, &b1, &l1) ? kit::OutText(b1, l1) : kit::OutNull(core::AuxType::String));
    }
    {
      const uint8_t *b2 = nullptr;
      size_t l2 = 0;
      row.values.push_back(secq6vgen_result_c2(r, i, &b2, &l2) ? kit::OutText(b2, l2) : kit::OutNull(core::AuxType::String));
    }
    {
      const uint8_t *b3 = nullptr;
      size_t l3 = 0;
      row.values.push_back(secq6vgen_result_c3(r, i, &b3, &l3) ? kit::OutText(b3, l3) : kit::OutNull(core::AuxType::String));
    }
    {
      uint64_t v4 = 0;
      row.values.push_back(secq6vgen_result_c4(r, i, &v4) ? kit::OutF64(v4) : kit::OutNull(core::AuxType::Double));
    }
    {
      int64_t v5 = 0;
      row.values.push_back(secq6vgen_result_c5(r, i, &v5) ? kit::OutI64(v5) : kit::OutNull(core::AuxType::Int64));
    }
    out.push_back(std::move(row));
  }
  secq6vgen_result_free(r);
  return true;
}

bool Execute(const void *s, const core::QueryArguments &a, std::vector<core::AuxRow> &out) {
  return Run(a, out, [&](auto... x) { return secq6vgen_execute(static_cast<const secq6vgen_state *>(s), x...); });
}

bool Answer(const void *s, const core::QueryArguments &a, std::vector<core::AuxRow> &out) {
  return Run(a, out, [&](auto... x) { return secq6vgens_answer(static_cast<const secq6vgens_reading *>(s), x...); });
}

